/**
 * fuec-assets.ts
 *
 * Script de configuración de assets FUEC.
 * Restaura los logos institucionales en /public/images/fuec/ si no existen.
 * Se ejecuta automáticamente durante el seed para garantizar persistencia
 * en cualquier entorno (Docker, nuevo servidor, reset de base de datos).
 *
 *   NO EDITAR MANUALMENTE  los datos base64 son los logos oficiales.
 *      Para actualizar logos, reemplazar los archivos en /public/images/fuec/
 *      y volver a ejecutar el script de generación.
 */

import fs from "fs";
import path from "path";

/** Par nombre-archivo / datos base64 */
interface AssetEntry {
    readonly filename: string;
    readonly base64: string;
}

const FUEC_ASSETS_DIR = path.join(process.cwd(), "public", "images", "fuec");

/**
 * Logos institucionales embebidos como base64.
 * Fuente: archivos originales proporcionados por la empresa.
 */
const ASSETS: readonly AssetEntry[] = [
    {
        filename: "logo-ministerio.png",
        base64: "",
    },
    {
        filename: "logo-coopetraes.png",
        base64: "",
    },
    {
        filename: "logo-supertransporte.png",
        base64: "",
    },
    {
        filename: "gerente-firma.png",
        base64: "",
    },
];

/**
 * Restaura un asset a disco solo si no existe.
 * No sobreescribe archivos existentes para preservar actualizaciones manuales.
 */
function restoreAssetIfMissing(entry: AssetEntry): void {
    const fullPath = path.join(FUEC_ASSETS_DIR, entry.filename);

    if (fs.existsSync(fullPath)) {
        console.log(`  ✓ (ya existe) ${entry.filename}`);
        return;
    }

    const buffer = Buffer.from(entry.base64, "base64");
    fs.writeFileSync(fullPath, buffer);
    console.log(`  ✅ Restaurado: ${entry.filename}`);
}

/**
 * Punto de entrada: garantiza que el directorio y todos los assets existen.
 */
export function setupFuecAssets(): void {
    console.log("  Verificando assets FUEC...");

    // Crear directorio si no existe
    if (!fs.existsSync(FUEC_ASSETS_DIR)) {
        fs.mkdirSync(FUEC_ASSETS_DIR, { recursive: true });
        console.log(`  📁 Directorio creado: ${FUEC_ASSETS_DIR}`);
    }

    for (const asset of ASSETS) {
        restoreAssetIfMissing(asset);
    }

    console.log("   Assets FUEC listos.");
}
